130	// files have no role structure and yield no exchanges.
131	//
132	// NOTE: deliberately a sibling of, not a replacement for,
133	// transcriptEpisodeSegments (reinforcement.go); see the divergence note there.
134	// Exchanges return only visible assistant narrative under a strict trust
135	// contract; episodes keep raw work text for commit detection. Keep the dialect
136	// switches in sync when adding a transcript format.
137	func scanConversationTranscript(path string) (conversationScanResult, error) {
138		return scanConversationTranscriptContext(context.Background(), path)
139	}
140	
141	func scanConversationTranscriptContext(ctx context.Context, path string) (conversationScanResult, error) {
142		before, err := os.Lstat(path)
143		if err != nil {
144			return conversationScanResult{}, err
145		}
146		if before.Mode()&os.ModeSymlink != 0 || !before.Mode().IsRegular() {
147			return conversationScanResult{}, fmt.Errorf("transcript is not a regular file: %s", path)
148		}
149		f, err := os.OpenFile(path, os.O_RDONLY|base.FileLockOpenFlags()|base.MemoryStateReadOpenFlags(), 0)
150		if err != nil {
151			return conversationScanResult{}, err
152		}
153		defer f.Close()
154		opened, err := f.Stat()
155		if err != nil || !opened.Mode().IsRegular() || !os.SameFile(before, opened) {
156			return conversationScanResult{}, fmt.Errorf("transcript changed or became unsafe while opening: %s", path)
157		}
158		result, scanErr := scanConversationTranscriptFileContext(ctx, f, path)
159		after, statErr := os.Lstat(path)
160		if statErr != nil || after.Mode()&os.ModeSymlink != 0 || !after.Mode().IsRegular() || !os.SameFile(opened, after) || after.Size() != opened.Size() || !after.ModTime().Equal(opened.ModTime()) {
161			return conversationScanResult{}, fmt.Errorf("transcript changed or became unsafe while reading: %s", path)
162		}
163		return result, scanErr
164	}
165	
166	func scanConversationTranscriptFileContext(ctx context.Context, f io.ReadSeeker, path string) (conversationScanResult, error) {
167		if ctx == nil {
168			ctx = context.Background()
169		}
170		if _, err := f.Seek(0, io.SeekStart); err != nil {
171			return conversationScanResult{}, err
172		}
173		probe := make([]byte, 4096)
174		n, readErr := contextCheckingReader{ctx: ctx, r: f}.Read(probe)
175		if readErr != nil && readErr != io.EOF {
176			return conversationScanResult{}, readErr
177		}
178		firstLine, _, _ := strings.Cut(strings.TrimSpace(string(probe[:n])), "\n")
