import { CopyCode } from "@/components/CopyCode"
import {
  StartLayout,
  StartStep,
  startCommandClassName,
} from "@/components/repositories/EmptyRepositoryStart"
import type { GetApiV1CacheByForgeByOrgByRepoMemoriesFacetsResponse } from "@/gen/api-sdk/types.gen"

import { MemoriesEmptySkeleton } from "./MemoriesEmptySkeleton"

export type MemoriesViewerState =
  GetApiV1CacheByForgeByOrgByRepoMemoriesFacetsResponse["viewerState"]

export function MemoriesEmptyState({
  viewerState,
}: {
  viewerState: MemoriesViewerState | "pending" | undefined
}) {
  if (viewerState === "pending") {
    // Same geometry as the onboarding panel, so a resolved `onboard` swaps
    // content without a layout jump.
    return <MemoriesEmptySkeleton />
  }
  if (viewerState === "onboard") {
    return (
      // Centered in the page's remaining height, like the empty repository page.
      <div className="flex flex-1 flex-col items-center justify-center py-8">
        <StartLayout
          title="Sync your first memory"
          description="Sync memories to Entire so your whole team can use them."
        >
          <StartStep icon={<Puzzle />} title="Install the Brain plugin">
            <CopyCode code="entire plugin install brain" codeClassName={startCommandClassName} />
          </StartStep>
          {/* Setup before connect: setup builds the local brain and starts
              distilling past sessions, so the first sync has something to
              push; its "Ready" output points at connect as the next step. */}
          <StartStep
            icon={<Brain />}
            title="Set up the brain"
            description="Run inside a local clone of this repository. Builds the local brain and starts distilling your past sessions into memories."
          >
            <CopyCode code="entire brain setup" codeClassName={startCommandClassName} />
          </StartStep>
          <StartStep icon={<Link />} title="Connect this repository">
            <CopyCode code="entire brain connect" codeClassName={startCommandClassName} />
          </StartStep>
        </StartLayout>
      </div>
    )
  }
  // Same outer geometry as the pending panel, so resolving to these states
  // does not shift the centered content or change its surface.
  return (
    <div className="flex w-full flex-1 flex-col items-center justify-center py-8">
      <p className="text-center text-muted">
        {viewerState === "askAdmin"
          ? "You need push access to publish memories. Ask a repo admin."
          : "No memories yet"}
      </p>
    </div>
  )
}
